// Regenerate extension/src/third_party/openpgp.js from OpenPGP.js's ES-module build.
//   npm install && node scripts/build-openpgp.mjs
//
// The single-file build has no eval/new Function, so it runs under the extension CSP
// `script-src 'self' 'wasm-unsafe-eval'` (JS eval stays blocked). Its only WebAssembly,
// Argon2 S2K, is loaded lazily when a file uses it; the iterated S2K Akari writes needs none.

import { readFile, writeFile, mkdir, copyFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const pkg = path.join(ROOT, 'node_modules/openpgp');
const outDir = path.join(ROOT, 'extension/src/third_party');
const { version } = JSON.parse(await readFile(path.join(pkg, 'package.json'), 'utf8'));
const src = await readFile(path.join(pkg, 'dist/openpgp.min.mjs'), 'utf8');

if (/\beval\s*\(|new Function\s*\(/.test(src)) throw new Error('openpgp build uses eval / new Function; it would break under the extension CSP');

await mkdir(outDir, { recursive: true });
await writeFile(path.join(outDir, 'openpgp.js'),
  `// OpenPGP.js ${version} (LGPL-3.0-or-later, https://openpgpjs.org) — dist/openpgp.min.mjs, only the source-map comment removed.\n`
  + `// Generated by scripts/build-openpgp.mjs — do not edit. License: openpgp.LICENSE\n`
  + src.replace(/\n\/\/# sourceMappingURL=\S+\s*$/, '\n'));
await copyFile(path.join(pkg, 'LICENSE'), path.join(outDir, 'openpgp.LICENSE'));
console.log(`third_party/openpgp.js: OpenPGP.js ${version}`);
